import{_ as a,o as e,c as l,a2 as i}from"./chunks/framework.1lR7qgqY.js";const p=JSON.parse('{"title":"M5 模型閘道與身分驗證","description":"","frontmatter":{},"headers":[],"relativePath":"build/m5-gateway-identity.md","filePath":"build/m5-gateway-identity.md","lastUpdated":null}'),o={name:"build/m5-gateway-identity.md"};function d(r,t,s,n,h,c){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="m5-模型閘道與身分驗證" tabindex="-1">M5 模型閘道與身分驗證 <a class="header-anchor" href="#m5-模型閘道與身分驗證" aria-label="Permalink to &quot;M5 模型閘道與身分驗證&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境, 符合條件才讀</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: llama-swap 授權 (訓練資料內資訊, 可能已過時); 另有一個 LiteLLM 漏洞據報預定於 2026-10-27 公開, 本章發布前須重新查證</li></ul></div><p><strong>結論</strong>: 單機單人不需要閘道. 只有多模型輪替而沒有多人治理需求時, 用 llama-swap 就夠. LiteLLM 有納入評估, 但不列為預設, 原因是一年內兩度成為供應鏈入侵的入口, 且集中保存上游金鑰 (信心: 高). 符合 M5.1 節的條件時, 閘道放在獨立的閘道區, 成為唯一保存 API 金鑰的地方; 帳號則交給身分驗證伺服器統一管理.</p><p><strong>這一塊在圖上的位置</strong>: VM 閘道區的 LiteLLM 與 VM 入口區的 Keycloak. <strong>前置模組</strong>: M1, M2. <strong>完成後的狀態</strong>: 每位使用者或每個應用各有一把虛擬金鑰與配額, 同事用同一組帳號登入所有介面.</p><h2 id="m5-1-何時不需要閘道" tabindex="-1">M5.1 何時不需要閘道 <a class="header-anchor" href="#m5-1-何時不需要閘道" aria-label="Permalink to &quot;M5.1 何時不需要閘道&quot;">​</a></h2><p>Ollama, llama-server 與 LM Studio 都已提供與 OpenAI 相容的 API, 介面可以直接連推論引擎 (信心: 高).</p><p>三項條件中符合任兩項, 才考慮加閘道 (信心: 中高; 「架構地圖」與「組裝總覽」引用此條件):</p><ol><li>3 人以上共用, 需要個別金鑰, 配額或用量紀錄.</li><li>同時混用雲端 API 與地端模型, 需要故障轉移.</li><li>多個應用程式要統一入口.</li></ol><p>沒有閘道時, 可用下列做法取代:</p><ul><li>介面直連推論引擎</li><li>用 llama-swap 處理模型切換</li><li>在反向代理 (Nginx 或 Caddy) 上做基本驗證與速率限制. Nginx 的速率限制 (<code>limit_req</code>) 為標準模組; Caddy 標準版不內建, 須另裝 caddy-ratelimit 外掛並重新編譯 (來源: 第三方教學, 待對照官方文件)</li><li>使用介面本身的使用者與權限管理 (Open WebUI, LibreChat)</li></ul><h2 id="m5-2-llama-swap-多模型輪替" tabindex="-1">M5.2 llama-swap: 多模型輪替 <a class="header-anchor" href="#m5-2-llama-swap-多模型輪替" aria-label="Permalink to &quot;M5.2 llama-swap: 多模型輪替&quot;">​</a></h2><p>llama-swap 是 Go 撰寫的單一執行檔, 以 YAML 設定, 依請求中的 model 欄位自動啟停 llama-server 或 vLLM. 它相容 OpenAI 與 Anthropic API, 並支援 API 金鑰. 2026 年持續發版, Go 模組在 2026-08-24 仍有更新 (來源: libraries.io 與多篇設定教學彙整; 授權為 MIT 屬訓練資料內資訊, 可能已過時, 請以官方儲存庫核對).</p><p>適用情境是一張顯示卡要輪流載入對話模型與嵌入模型, 也就是硬體等級 B, D, E (信心: 中高). 它只做模型切換, 不做多租戶治理, 因此風險等級低於完整閘道.</p><h2 id="m5-3-litellm-的使用條件與限制" tabindex="-1">M5.3 LiteLLM 的使用條件與限制 <a class="header-anchor" href="#m5-3-litellm-的使用條件與限制" aria-label="Permalink to &quot;M5.3 LiteLLM 的使用條件與限制&quot;">​</a></h2><h3 id="現況" tabindex="-1">現況 <a class="header-anchor" href="#現況" aria-label="Permalink to &quot;現況&quot;">​</a></h3><p>LiteLLM 程式庫採 MIT 授權, 但 <code>enterprise/</code> 目錄另有授權, SSO 等功能屬企業版 (來源: Maxim AI 與 TechJack Solutions 的比較文). Socket 的 PyPI 頁面顯示 litellm 1.107.0 的週下載量為 22,948,819 次.</p><h3 id="_2026-年兩次供應鏈事件" tabindex="-1">2026 年兩次供應鏈事件 <a class="header-anchor" href="#_2026-年兩次供應鏈事件" aria-label="Permalink to &quot;2026 年兩次供應鏈事件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>事件</th><th>來源</th></tr></thead><tbody><tr><td>2026-03-24</td><td>TeamPCP 先入侵 LiteLLM CI/CD 中未鎖定版本的 Trivy 掃描工具, 竊取 PyPI 發布權杖, 再發布含後門的 1.82.7 與 1.82.8</td><td>Snyk</td></tr><tr><td>2026-10-21</td><td>官方事故報告指出發布流程遭入侵, 攻擊者將惡意 v1.107.0 推送到 Docker registry 與 PyPI; 惡意 wheel 於 UTC 11:39 至 13:23 在 PyPI 上架; v1.107.0, latest, main-latest, main-stable 標籤都曾指向惡意映像; 惡意程式放在 Python 啟動檔 (cook.pth, sitecustomize.py), 只要 Python 啟動就會執行</td><td>LiteLLM 官方事故報告, Wiz, Help Net Security</td></tr></tbody></table><p>官方建議鎖定 <code>litellm==1.106.2</code>, 或 2026-10-21 之前發布的明確版本 (SOCRadar 轉述). 官方的攻擊鏈分析指出, 起點是 5 月 27 日有一組 master key 出現在公開儲存庫, 之後攻擊者竊得三組 GitHub 權杖. 官方說明企業版私有發行未受影響.</p><p>2026 年的 CVE 紀錄見<a href="/docs-handbook-poc/ref/versions">元件版本與安全公告頁</a>. 其中 CVE-2026-42208 為未驗證即可利用的 SQL 注入 (1.81.16 至 1.83.6, 修補於 1.83.7), 來源為 LiteLLM 官方部落格與 Bishop Fox.</p><h3 id="判斷" tabindex="-1">判斷 <a class="header-anchor" href="#判斷" aria-label="Permalink to &quot;判斷&quot;">​</a></h3><p>LiteLLM 的問題不在程式碼品質, 而在它是集中保存金鑰的高價值目標. 單機使用時, 它帶來的攻擊面大於效益. 多人環境則需要虛擬金鑰與配額, 此時須承擔其風險並落實下列措施 (信心: 中高):</p><ol><li>以映像摘要值 (digest) 鎖定版本, 不使用 latest 或 main-stable 標籤.</li><li>只放在內網, 並在反向代理層封鎖管理路徑 (<code>/health/test_connection</code>, MCP 路由).</li><li>不開啟 MCP 功能.</li><li>上游金鑰只給最低權限.</li><li>訂閱 GitHub Security Advisories.</li><li>事先準備好金鑰輪替流程 (見 O3).</li></ol><h3 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to &quot;替代方案&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>授權</th><th>定位</th><th>評語</th></tr></thead><tbody><tr><td>llama-swap</td><td>MIT (待核對)</td><td>模型切換</td><td>地端多模型首選</td></tr><tr><td>Bifrost (Maxim AI)</td><td>Apache 2.0</td><td>Go 閘道, 含虛擬金鑰, MCP 閘道, 語意快取</td><td>效能數字皆為廠商自測; SSO 與叢集屬企業版; 安全紀錄較短, 資料不足</td></tr><tr><td>Envoy AI Gateway, Kong AI Gateway, Apache APISIX</td><td>Apache 2.0</td><td>企業 API 管理延伸</td><td>須先會維運 Envoy 或 Kong, 對手冊讀者過重</td></tr></tbody></table><p>閘道延遲的公開數字互相矛盾 (約 1 至 5ms, 約 8ms, 約 40ms), 且全部來自競品廠商, 無法交叉驗證. 本機推論的生成時間以秒計, 因此延遲對單機使用者不是重點 (信心: 中, 屬推論).</p><h2 id="m5-4-身分驗證伺服器-keycloak" tabindex="-1">M5.4 身分驗證伺服器 (Keycloak) <a class="header-anchor" href="#m5-4-身分驗證伺服器-keycloak" aria-label="Permalink to &quot;M5.4 身分驗證伺服器 (Keycloak)&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>何時需要: 10 人以上, 或已有其他自架服務要共用帳號; 人少時用介面內建帳號即可</li><li>以 OIDC 串接 Open WebUI, LiteLLM 管理介面, Langfuse</li><li>串接公司既有帳號: AD, LDAP, 或 Google Workspace (須限制只允許公司網域)</li><li>離職停用流程: 停用一個帳號, 所有系統同時無法登入</li></ul><h2 id="m5-5-驗收測試" tabindex="-1">M5.5 驗收測試 <a class="header-anchor" href="#m5-5-驗收測試" aria-label="Permalink to &quot;M5.5 驗收測試&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>介面改經閘道連模型後, 對話仍正常</li><li>虛擬金鑰超過配額時, 閘道拒絕請求</li><li>推論伺服器只接受閘道區連線, 從入口區直接連線應失敗</li></ul>',32)])])}const u=a(o,[["render",d]]);export{p as __pageData,u as default};
